**独立参考解答（非原书摘录）**

下面给出一个可直接用 C99 编译的实现。输入格式定义为：先输入 n、m、w；随后恰输入 $m+w$ 个项目，每个项目先输入“项目号 取名前几名”（取值只能是 3 或 5），再按名次从 1 开始输入“姓名 学校号 成绩”。姓名和成绩字段均为不含空格、至多 63 字节的字符串；若实际名称含空格，可改为按整行读取。项目号 $1\ldots m$ 计入男子总分，$m+1\ldots m+w$ 计入女子总分。

~~~~c
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

enum {
    MAX_SCHOOL = 20, MAX_MEN = 30, MAX_WOMEN = 20,
    MAX_EVENT = MAX_MEN + MAX_WOMEN, MAX_AWARD = 5,
    MAX_AWARD_PER_SCHOOL = MAX_EVENT * MAX_AWARD, TEXT = 64
};

typedef struct {
    int eventNo, rank, score;
    char athlete[TEXT], result[TEXT];
} Award;

typedef struct {
    Award award[MAX_AWARD_PER_SCHOOL];
    int count, male, female;
} School;

static int points(int take, int rank) {
    static const int p5[] = {7, 5, 3, 2, 1};
    static const int p3[] = {5, 3, 2};
    return take == 5 ? p5[rank - 1] : p3[rank - 1];
}

int main(void) {
    int n, m, w;
    School school[MAX_SCHOOL + 1] = {0};
    bool seen[MAX_EVENT + 1] = {false};

    if (scanf("%d%d%d", &n, &m, &w) != 3 || n < 1 || n > MAX_SCHOOL ||
        m < 0 || m > MAX_MEN || w < 0 || w > MAX_WOMEN) {
        fprintf(stderr, "n、m、w 非法\n"); return 1;
    }

    for (int i = 0; i < m + w; ++i) {
        int eventNo, take;
        if (scanf("%d%d", &eventNo, &take) != 2 || eventNo < 1 ||
            eventNo > m + w || seen[eventNo] || (take != 3 && take != 5)) {
            fprintf(stderr, "项目号或取名规则非法\n"); return 1;
        }
        seen[eventNo] = true;
        for (int rank = 1; rank <= take; ++rank) {
            char name[TEXT], result[TEXT];
            int schoolNo;
            if (scanf("%63s%d%63s", name, &schoolNo, result) != 3 ||
                schoolNo < 1 || schoolNo > n ||
                school[schoolNo].count == MAX_AWARD_PER_SCHOOL) {
                fprintf(stderr, "获奖记录非法\n"); return 1;
            }
            Award *a = &school[schoolNo].award[school[schoolNo].count++];
            a->eventNo = eventNo; a->rank = rank; a->score = points(take, rank);
            snprintf(a->athlete, sizeof a->athlete, "%s", name);
            snprintf(a->result, sizeof a->result, "%s", result);
            if (eventNo <= m) school[schoolNo].male += a->score;
            else              school[schoolNo].female += a->score;
        }
    }

    for (int s = 1; s <= n; ++s) {
        printf("学校 %d 成绩单\n", s);
        if (school[s].count == 0) printf("  无获奖项目\n");
        for (int j = 0; j < school[s].count; ++j) {
            Award a = school[s].award[j];
            printf("  项目 %d，第 %d 名，%s，成绩 %s，得分 %d\n",
                   a.eventNo, a.rank, a.athlete, a.result, a.score);
        }
        printf("  男子 %d，女子 %d，团体 %d\n\n", school[s].male,
               school[s].female, school[s].male + school[s].female);
    }
    printf("校号  男子  女子  团体\n");
    for (int s = 1; s <= n; ++s)
        printf("%2d %5d %5d %5d\n", s, school[s].male, school[s].female,
               school[s].male + school[s].female);
    return 0;
}
~~~~

一组满足 $n=4,m=3,w=2$ 且奇号项目取前五、偶号项目取前三的测试输入为：

